    def _robust_json_decode(self, content_bytes):
        """ Attempts to decode JSON even if corrupted, concatenated, or missing commas. """
        if not content_bytes: return None
        try:
            return orjson.loads(content_bytes)
        except Exception:
            pass
        try:
            text = content_bytes.decode('utf-8', errors='ignore').strip()
        except Exception:
            return None
        if not text: return None
        try:
            obj, _ = json.JSONDecoder().raw_decode(text)
            return obj
        except Exception:
            pass
        try:
            text_fixed = re.sub(r'"\s+"', '", "', text)
            text_fixed = re.sub(r'}\s+{', '}, {', text_fixed)
            return orjson.loads(text_fixed)
        except Exception:
            pass
        try:
            if text.startswith('['):
                last_idx = text.rfind(']')
                if last_idx > 0: return orjson.loads(text[:last_idx+1])
            elif text.startswith('{'):
                last_idx = text.rfind('}')
                if last_idx > 0: return orjson.loads(text[:last_idx+1])
        except Exception:
            pass
        return None

    async def load_symbols_files(self):
        current_time = time.time()
        keys_loaded = False
        loaded_source = "None"

        async def _get_symbols(path: str) -> Set[str]:
            if not path: return set()
            p = Path(path)
            if not p.is_absolute(): p = Path(self.config.BASE_PATH) / path
            if not await aio_os.path.exists(p): return set()
            try:
                async with aiofiles.open(p, "rb") as f:
                    content = await f.read()
                    data = self._robust_json_decode(content)
                if isinstance(data, dict): data = data.get('symbols', []) or data.get('pairs', [])
                if isinstance(data, list): return {str(s).strip().upper() for s in data}
                return set()
            except Exception: return set()
        sym_ang_long_task = _get_symbols(getattr(self.config, 'SYMBOLS_ANG_LONG', 'symbols_ang_long.json'))
        sym_ang_short_task = _get_symbols(getattr(self.config, 'SYMBOLS_ANG_SHORT', 'symbols_ang_short.json'))
        sym_inf_long_task = _get_symbols(getattr(self.config, 'SYMBOLS_INF_LONG', 'symbols_inf_long.json'))
        sym_inf_short_task = _get_symbols(getattr(self.config, 'SYMBOLS_INF_SHORT', 'symbols_inf_short.json'))
        sym_flz_task = _get_symbols(getattr(self.config, 'SYMBOLS_FLZ', 'symbols_flz.json'))
        sym_men_task = _get_symbols(getattr(self.config, 'SYMBOLS_MEN', 'symbols_men.json'))
        sym_fin_task = _get_symbols(getattr(self.config, 'SYMBOLS_FIN', 'symbols_fin.json'))
        sym_active_task = _get_symbols(getattr(self.config, 'SYMBOLS_ACTIVE', 'symbols_active.json'))
        self.symbols_ang_long, self.symbols_ang_short, self.symbols_inf_long, self.symbols_inf_short, self.symbols_flz, self.symbols_men, self.symbols_fin, self.symbols_active = await asyncio.gather( sym_ang_long_task, sym_ang_short_task, sym_inf_long_task, sym_inf_short_task, sym_flz_task, sym_men_task, sym_fin_task, sym_active_task )
        if self.redis_manager:
            try:
                client = self.redis_manager.connections.get('local')
                if client:
                    raw = await client.get("tradeable_keys")
                    if raw:
                        if isinstance(raw, str): raw = raw.encode('utf-8')
                        keys_data = self._robust_json_decode(raw)
                        if isinstance(keys_data, list) and len(keys_data) > 5:
                            self.tradeable_keys = set(keys_data)
                            keys_loaded = True
                            loaded_source = "Redis"
            except Exception: pass
        json_path = Path(self.config.BASE_PATH) / "tradeable_keys.json"
        if not keys_loaded:
            try:
                if await aio_os.path.exists(json_path):
                    stat = await aio_os.stat(json_path)
                    age = current_time - stat.st_mtime
                    if age < 600: 
                        async with aiofiles.open(json_path, "rb") as f:
                            content = await f.read()
                            keys_data = self._robust_json_decode(content)
                            if isinstance(keys_data, list) and len(keys_data) > 5:
                                self.tradeable_keys = set(keys_data)
                                keys_loaded = True
                                loaded_source = "Global JSON"
            except Exception as e:
                logger.error(f"[SYMBOLS] Failed to load tradeable_keys.json: {e}")
        if not keys_loaded:
            try:
                await self.load_leaderboards()
                aggregated_keys = set()
                accounts_checked = 0
                for acc_key in self.accounts.keys():
                    tracker_file = Path(self.config.BASE_PATH) / acc_key / "tracker.json"
                    if await aio_os.path.exists(tracker_file):
                        async with aiofiles.open(tracker_file, "rb") as f:
                            try:
                                t_data = self._robust_json_decode(await f.read())
                                if t_data:
                                    t_keys = t_data.get('tradeable_position_keys', [])
                                    if isinstance(t_keys, list):
                                        valid_acc_keys = {k for k in t_keys if k.startswith(f"{acc_key}:")}
                                        aggregated_keys.update(valid_acc_keys)
                                        accounts_checked += 1
                            except Exception: pass
                if len(aggregated_keys) > 5:
                    self.tradeable_keys = aggregated_keys
                    keys_loaded = True
                    loaded_source = f"Tracker Aggregation ({accounts_checked} accs)"
            except Exception as e:
                logger.error(f"[SYMBOLS] Tracker aggregation failed: {e}")

    async def load_tradeable(self):
        current_time = time.time()
        if self.tradeable_keys and (current_time - self._last_tradeable_update < 180):
            return list(self.tradeable_keys)
        async with self.tradeable_lock:
            if self.tradeable_keys and (current_time - self._last_tradeable_update < 180):
                return list(self.tradeable_keys)
            keys_loaded_from_redis = False
            temp_keys = set()
            if self.redis_manager:
                try:
                    client = self.redis_manager.connections.get('local')
                    if client:
                        raw = await asyncio.wait_for(client.get("tradeable_keys"), timeout=0.5)
                        if raw:
                            if isinstance(raw, str): raw = raw.encode('utf-8')
                            data = self._robust_json_decode(raw)
                            if isinstance(data, list) and len(data) > 0:
                                temp_keys = {str(k).strip() for k in data}
                                keys_loaded_from_redis = True
                except Exception: pass
            main_path = config.BASE_PATH / "tradeable_keys.json"
            backup_path = config.BASE_PATH / "tradeable_keys.bak.json"

            async def load_file(p):
                if not p.exists(): return None
                try:
                    async with aiofiles.open(p, "rb") as f:
                        content = await f.read()
                        return self._robust_json_decode(content)
                except Exception as e:
                    logger.error(f"[SYMBOLS] Error loading {p.name}: {e}")
                    return None
            data = await load_file(main_path)
            if not data or not isinstance(data, list) or len(data) == 0:
                logger.warning(f"[SYMBOLS] Main keys file missing/corrupt. Trying backup...")
                data = await load_file(backup_path)
            if isinstance(data, list):
                file_keys = {str(k).strip() for k in data}
                if keys_loaded_from_redis:
                    temp_keys.update(file_keys)
                else:
                    temp_keys = file_keys
            if temp_keys:
                self.tradeable_keys = temp_keys
                self._last_tradeable_update = current_time
                self._last_file_read = current_time
            return list(self.tradeable_keys)

