            if is_augment and position_key in self.augmented_positions:
                _aug_dt = self.augmented_positions[position_key]
                if isinstance(_aug_dt, datetime):
                    _mins_ago = (datetime.now(timezone.utc) - _aug_dt).total_seconds() / 60
                    if _mins_ago < 15:
                        logger.warning(f"[AUG_POS_BLOCK] {position_key}: In augmented_positions ({_mins_ago:.1f}m ago), blocking duplicate")
