def calculate_htf_requirements(min_since_exit: float, htf_confirmations: list) -> bool:
    if not isinstance(htf_confirmations, list):
        return False
    if min_since_exit <= 120:
        return True
    count = len(htf_confirmations)
    if min_since_exit <= 480:
        return count >= 3
    elif min_since_exit <= 90 * 60:
        return count >= 5
    else:
        return count >= 7 

def format_reason(reason_code, i, side_params):
    """Helper to create a detailed reason string for logging."""
    i = {key: i.get(key, default) for key, default in { 'stoch_k_3m':50,'stoch_k_15m':50,'ha_3m':'neutral','ha_15m':'neutral','wt1_15m':0,'wt2_15m':0 }.items()}
    (k_3m,k_15m,ha_3m,ha_15m,wt1_15m,wt2_15m) = [i[k] for k in i]
    current_price = side_params.get('current_price', 0.0)
    timestamp = side_params.get('timestamp', '')
    return ( f"{reason_code} " f"k_3m={k_3m:.1f} " f"k_15m={k_15m:.1f} " f"ha3={ha_3m} " f"ha15={ha_15m} " f"wt1_15={wt1_15m:.1f} " f"wt2_15={wt2_15m:.1f} " f"price={current_price:.4f}" f"ts={timestamp}" )

def _parse_ranking_event_type(event_type: str):
    info = {"timeframe": None, "group": None, "direction": None, "raw_direction": None, "signal_type": None}
    if not isinstance(event_type, str):
        return info
    parts = event_type.split("_")
    if len(parts) >= 3 and parts[0] in {"winners", "losers"} and parts[1] == "all" and parts[2] in {"green", "red"}:
        info["group"] = parts[0]; info["signal_type"] = f"all_{parts[2]}"; info["direction"] = "entry" if (parts[0] == "winners" and parts[2] == "green") or (parts[0] == "losers" and parts[2] == "red") else "exit"; info["raw_direction"] = f"all_{parts[2]}"
        return info
    if len(parts) >= 4 and parts[0] in {"short", "long"} and parts[1] == "term" and parts[2] in {"winners", "losers"}:
        info["timeframe"] = "_".join(parts[0:2]); info["group"] = parts[2]; raw_dir = parts[3]; info["raw_direction"] = raw_dir
        if raw_dir in {"up", "jump"}:
            info["direction"] = "up"
        elif raw_dir in {"down", "drop"}:
            info["direction"] = "down"
    return info

def is_position_protected_by_reversed(ctx: dict, position_key: str) -> bool:
    trade_manager = ctx['trade_manager']
    account_key, symbol, position_side = parse_position_key(position_key)
    reversed_side = "SHORT" if position_side == "LONG" else "LONG"
    reversed_key = f"{account_key}:{symbol}_{reversed_side}"
    if reversed_key in trade_manager.reversed_positions:
        reversed_position = trade_manager.positions.get(reversed_key)
        if reversed_position and reversed_position.positionAmt > 0:
            return True # Block the action - original position is protected
    return False 

async def calculate_conviction(ctx):
    """Read conviction scores from indicators pipeline instead of calculating them."""
    cfg = ctx.get('config', config)
    if not getattr(cfg, 'ENABLE_CONVICTION', True):
        default_reason = ['CONVICTION_DISABLED']
        return 0.0, default_reason
    is_long = ctx['position_side'] == 'LONG'
    indicators_data = ctx.get('indicators', {})
    if is_long:
        conviction = indicators_data.get('zconviction_long', 0.0)
        reasons = indicators_data.get('zconviction_reasons_augment_long', [])
    else:
        conviction = indicators_data.get('zconviction_short', 0.0)
        reasons = indicators_data.get('zconviction_reasons_augment_short', [])
    if not isinstance(reasons, list):
        if isinstance(reasons, str):
            reasons = [reasons] if reasons else ['NO_REASONS']
        else:
            reasons = ['NO_REASONS']
    return float(conviction), reasons

def calculate_reduction_conviction(ctx):
    """Simplified reduction conviction - we don't use conviction for reductions."""
    cfg = ctx.get('config', config)
    if not getattr(cfg, 'ENABLE_CONVICTION', True):
        return 0.0, ['CONVICTION_DISABLED']
    is_long = ctx['position_side'] == 'LONG'
    indicators_data = ctx.get('indicators', {})
    conviction = 68.0 # Not used for reductions
    reasons = ['REDUCTION_CONVICTION_NOT_USED']
    return float(conviction), reasons

@timed_function("evaluate_reentry")
async def evaluate_reentry(ctx: dict) -> Optional[Signal]:
    global _last_events_cache
    now = datetime.now(timezone.utc); config = ctx['config']; logger = ctx['logger']; position_key = ctx['position_key']; symbol = ctx['symbol']; account_key = ctx['account_key']; position = ctx['trade_manager'].positions[position_key];trade_manager=ctx['trade_manager']
    if config.VERBOSE: logger.info(f"[REENTRY_START] {position_key}: Starting reentry evaluation - positionAmt={position.positionAmt:.6f}, gain={ctx.get('gain', 0):.2f}%") 
    gain = ctx['gain']; is_long = ctx['position_side'] == "LONG"; trade_manager = ctx['trade_manager']
    current_price = safe_fetch_float(ctx.get('current_price') or ctx.get('mark_price') or getattr(position,'mark_price',0.0),0.0)
    if not current_price: current_price = await price(symbol,position,3)
    positionAmt = safe_fetch_float(position.positionAmt, 0.0)
    position_value = abs(positionAmt) * current_price
    min_pos_size = safe_fetch_float(config.MIN_POSITION_SIZE, 55.0)
    if position_value > 2 * min_pos_size:
        logger.debug(f"[evaluate_reentry] {position_key}: SKIPPED - positionAmt value {position_value:.2f} > MIN_POSITION_SIZE {min_pos_size:.2f}")
        return None
    effective_min_qty = max(0.5 * config.START_POSITION_SIZE / current_price, trade_manager.min_qty.get(symbol, 0.0001) * 1.2 )
    if abs(float(position.positionAmt)) * current_price > 2 * config.START_POSITION_SIZE:
        return ReentryResult("Position too large", False, 0, 0, [], 0, f"Position too large: {position.positionAmt*current_price:.6f}")
    i = await ii(ctx['trade_manager'], symbol)
    conviction = i.get('zconviction_long', 0.0) if is_long else i.get('zconviction_short', 0.0); reasons = i.get('zconviction_reasons_augment_long', []) if is_long else i.get('zconviction_reasons_augment_short', []); 
    raw_reasons = i.get('zconviction_reasons_augment_long', []) if is_long else i.get('zconviction_reasons_augment_short', [])
    if isinstance(raw_reasons, list):
        reasons = [str(r) for r in raw_reasons]
    elif isinstance(raw_reasons, str):
        reasons = [raw_reasons]
    else:
        reasons = ['NO_REASONS'] 
    if config.VERBOSE: logger.info(f"[REENTRY_INDICATORS] {position_key}: ${position.positionAmt*current_price} price={current_price:.6f} gain={gain:.2f}% positionAmt={position.positionAmt:.6f} conviction={conviction:.2f} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}")
    process_position_enter_count[position_key] = process_position_enter_count.get(position_key, 0) + 1
    if process_position_enter_count[position_key] % 10 == 5: logger.info(f"[REENTRY_ENTERRRRR] {position_key} count={process_position_enter_count[position_key]}")
    k_3m,d_3m,k_15m,d_15m,k_1h,k_4h = i.get('stoch_k_3m'),i.get('stoch_d_3m'),i.get('stoch_k_15m'),i.get('stoch_d_15m'),i.get('stoch_k_1h'),i.get('stoch_k_4h')
    t_up_3m,t_up_15m = i.get('t_up_3m',False),i.get('t_up_15m',True)
    high_15m = safe_fetch_float(i.get('high_15m', 0), 0.0); high_15m_prev = safe_fetch_float(i.get('high_15m_prev', 0), 0.0); low_15m = safe_fetch_float(i.get('low_15m', 0), 0.0); low_15m_prev = safe_fetch_float(i.get('low_15m_prev', 0), 0.0); ha_3m = i.get('ha_3m', 'neutral') or 'neutral'; ha_15m = i.get('ha_15m', 'neutral') or 'neutral'
    higher_high_15m = high_15m > high_15m_prev and (low_15m > low_15m_prev or ha_15m=='green') if high_15m > 0 and high_15m_prev > 0 and low_15m > 0 and low_15m_prev > 0 else False
    lower_low_15m = (high_15m < high_15m_prev or ha_15m=='red') and low_15m < low_15m_prev if high_15m > 0 and high_15m_prev > 0 and low_15m > 0 and low_15m_prev > 0 else False
    t_up_15m_override = (is_long and (higher_high_15m or (k_15m > d_15m if k_15m and d_15m else False))) or (not is_long and (lower_low_15m or (k_15m < d_15m if k_15m and d_15m else False)))
    t_up_15m_effective = t_up_15m if not t_up_15m_override else (True if is_long else False)
    ha_1h = i.get('ha_1h', 'neutral')
    strong_trend_long = is_long and ha_1h == 'green' and t_up_15m
    strong_trend_short = not is_long and ha_1h == 'red' and not t_up_15m
    higher_high_15m = bool(i.get('high_15m', 0) and i.get('high_15m_prev', 0) and i.get('high_15m', 0) >= i.get('high_15m_prev', 0))
    lower_low_15m = bool(i.get('low_15m', 0) and i.get('low_15m_prev', 0) and i.get('low_15m', 0) <= i.get('low_15m_prev', 0))
    trend_up = (t_up_3m or ha_3m == 'green' or k_3m > d_3m) and (k_15m > d_15m or higher_high_15m)
