    async def s10_the_army_reentry() -> ReentryResult:
        """ The Holy Grail Reentry: Massive previous breakout, now resting on SMA 15m. (dc_15_high - dc_15m_low) / dc_15m_low > 5 * usual """
        dc_width_15m_pct = ((dc_high_15m - dc_low_15m) / dc_low_15m) * 100 if dc_low_15m > 0 else 0
        is_massive_expansion = dc_width_15m_pct > 4.5
        dist_to_sma = abs(current_price - sma_200_15m) / sma_200_15m if sma_200_15m > 0 else 1.0
        is_at_sma = dist_to_sma < 0.015 # Within 1.5% of the SMA
        is_reset = (is_long and k_15m < 35) or (not is_long and k_15m > 65)
        is_triggering = (is_long and k_3m > d_3m and t_up_3m) or (not is_long and k_3m < d_3m and not t_up_3m)
        should_trigger = is_massive_expansion and is_at_sma and is_reset and is_triggering
        if should_trigger:
            quantity = config.START_POSITION_SIZE * 5.0 / current_price 
            conviction = 95.0
            reasons = ["BRING_OUT_THE_ARMY", f"DC_EXP={dc_width_15m_pct:.1f}%", f"SMA_RETEST={dist_to_sma*100:.2f}%"]
            logger.critical(f"🚀💂‍♂️ [DEPLOY_THE_ARMY] {position_key}: Perfect Post-Breakout Consolidation Retest. Firing heavy.")
            return ReentryResult("s10_army_reentry", True, quantity, conviction, reasons, 0.95)
        return ReentryResult("s10_army_reentry", False, 0, 0, [], 0, "Army conditions not met")

