def _apply_sentiment_boost(reasons, sentiment_boost_factor):
    """Apply sentiment boost to reasons list"""
    if isinstance(reasons, list):
        reasons = reasons.copy()
    else:
        reasons = [str(reasons)]
    if sentiment_boost_factor > 1.0:
        reasons.append(f"SENTIMENT_BOOST_{sentiment_boost_factor:.1f}x")
    return reasons


@timed_function("evaluate_technical_indicator_signals")
async def evaluate_technical_indicator_signals(ctx: dict) -> Optional[Signal]: # REQUIRED INDICATORS FOR THIS FUNCTION: (43 indicators - stochastic, DC basis, wave trend, price, HA, ATR, BB, SMA)
    now = datetime.now(timezone.utc)
    account_key = ctx['account_key']
    signal_data = ctx.get('signal_data')
    event_type = signal_data.get('event_type', '') if signal_data else ctx.get('event_type') or 'account_update'
    if event_type == 'account_update' or 'periodic' in event_type:
        return None
    symbol = ctx.get('symbol', 'UNKNOWN')
    config = ctx['config']
    logger = ctx['logger']
    position_key = ctx['position_key']
    gain = ctx['gain']
    trade_manager=ctx['trade_manager']
    position = await trade_manager.get_position(position_key)
    current_price = await price(ctx['symbol'], position)
    if not current_price or current_price <= 0: current_price = await price(ctx['symbol'], position)
    await _ensure_indicator_snapshot(ctx)
    i = await ii(ctx['trade_manager'], ctx['symbol'])
    if not i: logger.warning(f"[{position_key}] TECHNICAL_INDICATOR_NOT_ALLOWED: No indicator data"); return None
    logger.debug(f" REDIS SIGNAL RECEIVED: evaluate_technical_indicator_signals processing {event_type} for {position_key}")
    trade_manager = ctx['trade_manager']
    is_long = ctx['position_side'] == 'LONG'
    conviction_long = float(ctx.get('conviction_long', 0.0))
    conviction_short = float(ctx.get('conviction_short', 0.0))
    raw_reasons_long = ctx.get('conviction_long_reasons', [])
    raw_reasons_short = ctx.get('conviction_short_reasons', [])
    action_from_signal = ((signal_data.get('action') if signal_data else '') or '').upper()
    winners_all_green_rank = 'winners_all_green_rank' in event_type
    losers_all_red_rank = 'losers_all_red_rank' in event_type
    critical_rank_signal = winners_all_green_rank or losers_all_red_rank
    data_is_stale = False
    penalties: List[str] = []
    staleness_thresholds = { '3m': timedelta(minutes=6), '15m': timedelta(minutes=20), '1h': timedelta(hours=1.2), '4h': timedelta(hours=5), }
    for tf, threshold in staleness_thresholds.items():
        tf_ts_str = i.get(f'timestamp_{tf}')
        if tf_ts_str:
            try:
                tf_ts = isoparse(tf_ts_str)
                age = now - tf_ts
                if age > threshold:
                    logger.warning(f"[{position_key}] Data for {tf} timeframe is {age.total_seconds():.0f}s old (> {threshold.total_seconds():.0f}s threshold)")
                    data_is_stale = True
                    penalties.append(f"{tf}_STALE")
                    break
            except Exception:
                continue
    if data_is_stale:
        logger.warning(f"[{position_key}] Data is stale - lowering conviction for ENTER signals instead of blocking")
    if isinstance(raw_reasons_long, (list, tuple, set)):
        reasons_long = [str(r) for r in raw_reasons_long]
    elif raw_reasons_long:
        reasons_long = [str(raw_reasons_long)]
    else:
        reasons_long = []
    if isinstance(raw_reasons_short, (list, tuple, set)):
        reasons_short = [str(r) for r in raw_reasons_short]
    elif raw_reasons_short:
        reasons_short = [str(raw_reasons_short)]
    else:
        reasons_short = []
    current_price = await price(ctx['symbol'], position)
    if not current_price or current_price <= 0:
        current_price = i.get('current_price', 0) if isinstance(i, dict) else position.mark_price
        if not current_price or current_price <= 0:
            logger.error(f"[{position_key}] No valid price available from price() or indicators, aborting")
            return None
    now = datetime.now(timezone.utc)
    conviction=conviction_long if is_long else conviction_short
    reasons=raw_reasons_long if is_long else raw_reasons_short
    essential_indicators = {'stoch_k_15m': 0, 'stoch_d_15m': 0, 'stoch_k_1h': 0, 'stoch_d_1h': 0, 'stoch_k_15m_prev': 0, 'stoch_k_1h_prev': 0, 'stoch_crossover_3m': False, 'stoch_crossunder_3m': False,'stoch_crossover_15m': False, 'stoch_crossunder_15m': False, 'stoch_crossover_1h': False, 'stoch_crossunder_1h': False, 'wt1_3m': 0, 'wt2_3m': 0, 'wt1_15m': 0, 'wt2_15m': 0, 'wt1_1h': 0, 'wt2_1h': 0,'wt_crossover_15m': False, 'wt_crossover_1h': False, 'sma_200_1m': 0, 'sma_200_15m': 0, 'dc_basis_3m': 0, 'dc_basis_15m': 0,'dc_high_15m': 0, 'dc_low_15m': 0, 'ha_3m': 'neutral', 'ha_15m': 'neutral', 'atr_15m': 0, 'atr_1h': 0,'mfi_15m': 50, 'mfi_1h': 50,'relative_volume_15m': 1.0, 'relative_volume_3m': 1.0,'lr_trend_15m': 0, 'lr_trend_1h': 0, 'lr_trend_4h': 0, '0market_sentiment_local': 50.0, '0market_sentiment_score': 50.0,'0ranking_points': 50.0, '0ranking_points_global': 50.0, '0sentiment_classification': 'NEUTRAL', '0sentiment_strength': 0.0, '0sentiment_rank': -1, '0is_top_sentiment': False, '0is_bottom_sentiment': False, 'timestamp': 0, 'current_price': 0}
    indicators_cache = {key: i.get(key, default) for key, default in essential_indicators.items()}
    (k_15m, d_15m, k_1h, d_1h, k_15m_prev, k_1h_prev, stoch_crossover_3m, stoch_crossunder_3m, stoch_crossover_15m, stoch_crossunder_15m,stoch_crossover_1h, stoch_crossunder_1h, wt1_3m, wt2_3m, wt1_15m, wt2_15m, wt1_1h, wt2_1h, wt_crossover_15m, wt_crossover_1h, sma_200_1m, sma_200_15m, dc_basis_3m, dc_basis_15m, dc_high_15m, dc_low_15m, ha_3m, ha_15m, atr_15m, atr_1h, mfi_15m, mfi_1h,relative_volume_15m, relative_volume_3m, lr_trend_15m, lr_trend_1h, lr_trend_4h, market_sentiment_local, market_sentiment, ranking_points, ranking_points_global, sentiment_classification, sentiment_strength, sentiment_rank, is_top_sentiment, is_bottom_sentiment,timestamp, _) = [indicators_cache[k] for k in essential_indicators]
    if config.VERBOSE:
        logger.info(f"[TECHNICAL_INDICATORS_SIGNALS] {position_key}: pA${position.positionAmt*current_price} price={current_price:.6f} gain={gain:.2f}% positionAmt={position.positionAmt:.6f} account_key={account_key} event_type={event_type}")
    if not critical_rank_signal and position.positionAmt > max(config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol,0.001)) and gain < 0.2 * config.MIN_GAIN_TO_BUY_AGGRESSIVELY:
        logger.info(f"[TECHNICAL_INDICATORS_SIGNALS] REJECTED GAIN TOO LOW {gain} {position_key}: ${position.positionAmt*current_price:.2f} price={current_price:.6f} gain={gain:.2f}% positionAmt={position.positionAmt:.6f} event_type={event_type} {signal_data}")
        penalties.append('LOW_GAIN')
    if not critical_rank_signal and ((is_long and k_15m < k_15m_prev or ha_3m == 'red' or ha_15m=='red' or wt1_3m < wt2_3m or wt1_15m < wt2_15m) or (not is_long and k_15m > k_15m_prev or ha_3m == 'green' or ha_15m=='green' or wt1_3m > wt2_3m or wt1_15m > wt2_15m)):
        logger.info(f"[TECHNICAL_INDICATORS_SIGNALS] {position_key}: Price not trending in position direction")
        penalties.append('TREND_MISMATCH')
    if winners_all_green_rank or losers_all_red_rank:
        logger.critical(f"[{position_key}] CRITICAL RANKING SIGNAL RECEIVED: {event_type} action={action_from_signal}")
    if account_key in ['inf','men','fin','ang','flz']:
        if action_from_signal in ['BUY', 'SELL'] and any(ranking_signal in event_type for ranking_signal in ['winners_up_rank', 'winners_down_rank', 'losers_jump_rank', 'losers_drop_rank', 'winners_all_green_rank', 'losers_all_red_rank', 'WT Strong Alert']):
            logger.info(f"[{position_key}] 🎯 MEN AUTO-FOLLOW: Evaluating {action_from_signal} signal from {event_type}")
            if action_from_signal == 'BUY' and is_long:
                if position.positionAmt < max(max(config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol,0.001)) , ctx.get('trade_manager').min_qty.get(symbol, 0.0001)):
                    if config.VERBOSE:
                        logger.info(f"[TECHNICAL_INDICATORS_RETURN] {position_key}: OPEN - MEN_AUTO_FOLLOW_BUY action_from_signal={action_from_signal} event_type={event_type} conviction={conviction:.2f} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}")
                    if winners_all_green_rank or losers_all_red_rank:
                        logger.critical(f"[{position_key}] CRITICAL EXECUTION: {event_type} -> OPEN MEN AUTO-FOLLOW")
                    return Signal(action='OPEN', reason=f'MEN_AUTO_FOLLOW_BUY_{event_type} ts3/15:{i.get("timestamp_3m")}/{i.get("timestamp_15m")}| {reasons}', conviction=conviction)
                elif position.positionAmt > max(max(config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol,0.001)) , ctx.get('trade_manager').min_qty.get(symbol, 0.0001)) and (gain > 0.5 * config.MIN_GAIN_TO_BUY_AGGRESSIVELY or winners_all_green_rank):
                    if config.VERBOSE:
                        logger.info(f"[TECHNICAL_INDICATORS_RETURN] {position_key}: AUGMENT - MEN_AUTO_FOLLOW_BUY_AUGMENT action_from_signal={action_from_signal} event_type={event_type} gain={gain:.2f} conviction={conviction:.2f} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}")
                    if winners_all_green_rank or losers_all_red_rank:
                        logger.critical(f"[{position_key}] CRITICAL EXECUTION: {event_type} -> AUGMENT MEN AUTO-FOLLOW")
                    return Signal(action='AUGMENT', reason=f'MEN_AUTO_FOLLOW_BUY_AUGMENT_{event_type} ts3/15:{i.get("timestamp_3m")}/{i.get("timestamp_15m")}| {reasons}', conviction=conviction)
            elif action_from_signal == 'SELL' and not is_long:
                if position.positionAmt < max(max(config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol,0.001)) , ctx.get('trade_manager').min_qty.get(symbol, 0.0001)):
                    if config.VERBOSE:
                        logger.info(f"[TECHNICAL_INDICATORS_RETURN] {position_key}: OPEN - MEN_AUTO_FOLLOW_SELL action_from_signal={action_from_signal} event_type={event_type} conviction={conviction:.2f} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}")
                    if winners_all_green_rank or losers_all_red_rank:
                        logger.critical(f"[{position_key}] CRITICAL EXECUTION: {event_type} -> OPEN MEN AUTO-FOLLOW")
                    return Signal(action='OPEN', reason=f'MEN_AUTO_FOLLOW_SELL_{event_type} ts3/15:{i.get("timestamp_3m")}/{i.get("timestamp_15m")}| {reasons}', conviction=conviction)
                elif position.positionAmt > max(max(config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol,0.001)) , ctx.get('trade_manager').min_qty.get(symbol, 0.0001)) and (gain > 0.5 * config.MIN_GAIN_TO_BUY_AGGRESSIVELY or losers_all_red_rank):
                    if config.VERBOSE:
                        logger.info(f"[TECHNICAL_INDICATORS_RETURN] {position_key}: AUGMENT - MEN_AUTO_FOLLOW_SELL_AUGMENT action_from_signal={action_from_signal} event_type={event_type} gain={gain:.2f} conviction={conviction:.2f} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}")
                    if winners_all_green_rank or losers_all_red_rank:
                        logger.critical(f"[{position_key}] CRITICAL EXECUTION: {event_type} -> AUGMENT MEN AUTO-FOLLOW")
                    return Signal(action='AUGMENT', reason=f'MEN_AUTO_FOLLOW_SELL_AUGMENT_{event_type} ts3/15:{i.get("timestamp_3m")}/{i.get("timestamp_15m")}| {reasons}', conviction=conviction)
    relaxed_signal = await evaluate_technical_indicator_signals_new(ctx)
    if relaxed_signal:
        base_conviction = relaxed_signal.conviction if isinstance(relaxed_signal.conviction, (int, float)) else 0.0
        if base_conviction == 0.0:
            base_conviction = conviction_long if is_long else conviction_short
            if base_conviction == 0.0:
                base_conviction = 35.0 if is_long else -35.0
        if penalties:
            penalty_factor = 0.6 if data_is_stale else 0.8
            base_conviction = float(base_conviction) * penalty_factor
            relaxed_signal.reason = f"{relaxed_signal.reason} | RELAXED:{','.join(penalties)}"
        relaxed_signal.conviction = float(base_conviction)
        return relaxed_signal


@timed_function("evaluate_technical_indicator_signals_new")
async def evaluate_technical_indicator_signals_new(ctx: dict) -> Optional[Signal]:
    event_type = _normalize_event_type(ctx)
    if event_type == 'account_update' or 'periodic' in event_type:
        return None
    trade_manager = ctx.get('trade_manager')
    if not trade_manager:
        return None
    position = trade_manager.positions.get(ctx['position_key'])
    if not position:
        return None
    i = await ii(ctx['trade_manager'], ctx['symbol'])  
    if not _check_timestamp_3m_freshness(i, max_age_minutes=8.0):
        return None    
    is_long = ctx.get('position_side') == 'LONG'
    signal_data = ctx.get('signal_data') or {}
    detected: List[str] = []

    event_hint = signal_data.get('event_type')
    if isinstance(event_hint, str) and event_hint:
        detected.append(event_hint)
    for key in ('stoch_crossover_3m', 'stoch_crossover_15m', 'wt_crossover_15m', 'dc_basis_crossover_15m'):
        if signal_data.get(key):
            detected.append(key)
    if not detected:
        for key in ('stoch_crossover_3m', 'stoch_crossover_15m', 'wt_crossover_15m', 'dc_basis_crossover_15m'):
            if i.get(key):
                detected.append(key)
        ha_val = i.get('ha_15m')
        if ha_val == ('green' if is_long else 'red'):
            detected.append(f'ha_{ha_val}_15m')
    if not detected:
        return None
    def _supportive(sig: str) -> bool:
        if is_long:
            return any(term in sig for term in ('crossover', 'BUY', 'ha_green'))
        return any(term in sig for term in ('crossunder', 'SELL', 'ha_red'))
    positives = [sig for sig in detected if _supportive(sig)]
    if not positives:
        return None
    min_qty = 0.0
    symbol = ctx.get('symbol')
    if hasattr(trade_manager, 'min_qty') and isinstance(trade_manager.min_qty, dict):
        min_qty = safe_fetch_float(trade_manager.min_qty.get(symbol), 0.0)
    positionAmt = safe_fetch_float(getattr(position, 'positionAmt', 0.0), 0.0)
    action = _decide_action(positionAmt, min_qty)
    conviction_key = 'conviction_long' if is_long else 'conviction_short'
    conviction = safe_fetch_float(ctx.get(conviction_key), 25.0)
    reasons_key = 'conviction_long_reasons' if is_long else 'conviction_short_reasons'
    reasons = ctx.get(reasons_key) or []
    reason_parts = [f"TECH_SIGNAL_{positives[0]}"]
    if reasons:
        reason_parts.append(", ".join(str(r) for r in reasons if r))
    reason = " | ".join(part for part in reason_parts if part)
    return Signal(action=action, reason=reason, conviction=conviction)
async def _handle_auto_follow_signal(ctx, action, event_type, current_price, min_position_size):
    """Handle MEN account auto-follow signals"""
    position = ctx['trade_manager'].positions[ctx['position_key']]
    gain = ctx['gain']
    config = ctx['config']
    if action == 'BUY' and ctx['position_side'] == 'LONG':
        conviction = ctx['conviction_long']
        reasons = ctx['conviction_long_reasons']
        if position.positionAmt < min_position_size:
            return Signal(action='OPEN', reason=f'MEN_AUTO_FOLLOW_BUY_{event_type}| {reasons}', conviction=conviction)
        elif gain > 0.5 * config.MIN_GAIN_TO_BUY_AGGRESSIVELY:
            return Signal(action='AUGMENT', reason=f'MEN_AUTO_FOLLOW_BUY_AUGMENT_{event_type} | {reasons}', conviction=conviction)
    elif action == 'SELL' and ctx['position_side'] != 'LONG':
        conviction = ctx.get('conviction_short', 0.0)
        reasons = ctx.get('conviction_short_reasons', [])
        if position.positionAmt < min_position_size:
            return Signal(action='OPEN', reason=f'MEN_AUTO_FOLLOW_SELL_{event_type} | {reasons}', conviction=conviction)
        elif gain > 0.5 * config.MIN_GAIN_TO_BUY_AGGRESSIVELY:
            return Signal(action='AUGMENT', reason=f'MEN_AUTO_FOLLOW_SELL_AUGMENT_{event_type} | {reasons}', conviction=conviction)
    return None
async def _calculate_sentiment_boost(ctx, is_long, market_sentiment_local, market_sentiment, is_top_sentiment, is_bottom_sentiment):
    """Calculate sentiment boost factor"""
    sentiment_boost_factor = 1.0
    sentiment_easy_entry = False
    
    if is_long:
        if market_sentiment > 20 and market_sentiment_local > 60:
            sentiment_easy_entry = True
            sentiment_boost_factor = 1.5
        elif market_sentiment < -30 and market_sentiment_local < -40 and is_bottom_sentiment:
            sentiment_easy_entry = True
            sentiment_boost_factor = 2.0
        elif market_sentiment < -50 and not sentiment_easy_entry:
            ctx['logger'].info(f"[{ctx['position_key']}] TRADE NOT_ALLOWED: Market too bearish for long")
            return 0.0, False
    else:
        if market_sentiment < -20 and market_sentiment_local < -60:
            sentiment_easy_entry = True
            sentiment_boost_factor = 1.5
        elif market_sentiment > 30 and market_sentiment_local > 40 and is_top_sentiment:
            sentiment_easy_entry = True
            sentiment_boost_factor = 2.0
    ctx['sentiment_boost_factor'] = sentiment_boost_factor
    ctx['sentiment_easy_entry'] = sentiment_easy_entry
    return sentiment_boost_factor, sentiment_easy_entry

async def _validate_sentiment_constraints(ctx, is_long, ranking_points, market_sentiment, sentiment_easy_entry):
    """Validate sentiment-based constraints"""
    if is_long and ranking_points < 50:
        ctx['logger'].info(f"[{ctx['position_key']}] TRADE NOT_ALLOWED: Symbol ranking too poor for long")
        return False
    elif not is_long and ranking_points > 50:
        ctx['logger'].info(f"[{ctx['position_key']}] TRADE NOT_ALLOWED: Symbol ranking too strong for short")
        return False
    return True
async def _validate_technical_conditions(ctx, is_long, atr_15m, atr_1h, mfi_15m, mfi_1h, lr_trend_15m, lr_trend_1h, lr_trend_4h, relative_volume_15m, relative_volume_3m,current_price, dc_high_15m, dc_low_15m):
    logger = ctx['logger']
    position_key = ctx['position_key']
    if is_long and (mfi_15m > 85 or mfi_1h > 80):
        if config.VERBOSE: logger.info(f"[{position_key}] TRADE NOT_ALLOWED: MFI overbought")
        return False
    if not is_long and (mfi_15m < 10 or mfi_1h < 15):
        logger.info(f"[{position_key}] TRADE NOT_ALLOWED: MFI oversold")
        return False
    if is_long:
        positive_trends = sum(1 for trend in [lr_trend_15m, lr_trend_1h, lr_trend_4h] )
        if positive_trends < 2:
            if config.VERBOSE: logger.info(f"[{position_key}] TRADE NOT_ALLOWED: Insufficient positive trends")
            return False
    else:
        negative_trends = sum(1 for trend in [lr_trend_15m, lr_trend_1h, lr_trend_4h] if trend < 0)
        if negative_trends < 1:
            logger.info(f"[{position_key}] TRADE NOT_ALLOWED: No negative trends for short")
            return False
    if is_long and relative_volume_15m < 1.1 and relative_volume_3m < 1.1:
        if config.VERBOSE: logger.info(f"[{position_key}] TRADE NOT_ALLOWED: Insufficient volume")
        return False
    if not is_long and relative_volume_15m < 0.5 and relative_volume_3m < 0.5:
        logger.info(f"[{position_key}] TRADE NOT_ALLOWED: Extremely low volume")
        return False
    if dc_high_15m and dc_low_15m:
        price_range = dc_high_15m - dc_low_15m
        if price_range > 0:
            distance_to_high = abs(current_price - dc_high_15m) / price_range
            distance_to_low = abs(current_price - dc_low_15m) / price_range
            if distance_to_high < 0.025 or distance_to_low < 0.025:
                logger.info(f"[{position_key}] TRADE NOT_ALLOWED: Too close to DC boundaries")
                return False
    return True
async def _validate_timeframe_confirmation(ctx, timeframe, stoch_crossover_15m, stoch_crossover_1h,  wt_crossover_15m, wt_crossover_1h):
    if timeframe in ["1h", "4h", "D"]:
        lower_tf_signals = []
        if timeframe == "1h":
            lower_tf_signals = [stoch_crossover_15m, wt_crossover_15m]
        elif timeframe == "4h":
            lower_tf_signals = [stoch_crossover_1h, wt_crossover_1h]
        if not any(lower_tf_signals):
            ctx['logger'].info(f"[{ctx['position_key']}] TRADE NOT_ALLOWED: No lower timeframe confirmation")
            return False
    return True

async def calculate_final_order_quantity(position_key: Optional[str] = None, account_key: Optional[str] = None, symbol: Optional[str] = None, position: 'Position' = None, action: str = "", trade_manager: 'MultiAccountTradeManager' = None, conviction: float = 0.5, base_quantity: float = 0.0, reason: str = "", signal_data=None) -> float:
    if not any(s in action.upper() for s in ['OPEN', 'AUGMENT', 'REENTRY']):
        return base_quantity
    i = await ii(trade_manager, symbol)
    now, config = datetime.now(timezone.utc), trade_manager.config
    current_price = float(position.mark_price) if position.mark_price > 0 else await quick_price(symbol)
    if current_price == 0.0 or current_price is None:
        logger.critical(f'[CRITICAL_MARK_PRICE_MISSING] {position_key}: mark_price missing in calculate_final_order_quantity! Attempting refresh before restart...')
        try:
            refreshed_position = await trade_manager.get_position(position_key)
            current_price = await price(symbol, position) or float(refreshed_position.mark_price) if refreshed_position and refreshed_position.mark_price > 0 else 0.0
        except Exception as e:
            logger.error(f"[{position_key}] Error refreshing position/price: {e}")
            current_price = 0.0
    if current_price <= 0.0:
        logger.error(f"[calculate_final_order_quantity] {position_key}: Invalid current_price={current_price}, returning base_quantity={base_quantity}")
        return base_quantity
    is_long = position.position_side == "LONG"
    if config.VERBOSE:logger.info(f"[final_order_quantity] {position_key}: ${current_price * base_quantity:.2f} qty={base_quantity:.4f} price={current_price:.6f}")
    factors: List[Tuple[float, bool, str]] = []
    sizing_score = 0.0
    if i.get('relative_volume_3m', 1.0) > 1.2: factors.append((6, True, "High RV 3m (>1.2)"))
    if i.get('relative_volume_15m', 1.0) > 1.2: factors.append((6, True, "High RV 15m (>1.2)"))
    if i.get('relative_volume_3m', 1.0) < 0.9: factors.append((-6, True, "Low RV 3m (<0.9)"))
    if i.get('relative_volume_15m', 1.0) < 0.9: factors.append((-6, True, "Low RV 15m (<0.9)"))
    lr_up_count = sum(2 for tf in ['lr_trend_15m', 'lr_trend_1h', 'lr_trend_4h'] if i.get(tf) == "up")
    lr_down_count = sum(2 for tf in ['lr_trend_15m', 'lr_trend_1h', 'lr_trend_4h'] if i.get(tf) == "down")
    mfi_up_count = sum(1 for tf in ['mfi_trend_3m', 'mfi_trend_15m', 'mfi_trend_1h', 'mfi_trend_4h'] if i.get(tf) == "up")
    mfi_down_count = sum(1 for tf in ['mfi_trend_3m', 'mfi_trend_15m', 'mfi_trend_1h', 'mfi_trend_4h'] if i.get(tf) == "down")
    if is_long:
        factors.extend([ (10 * lr_up_count, lr_up_count > 0, f"HTF LR Up-Trend ({lr_up_count})"), (-20 * lr_down_count, lr_down_count > 0, f"Conflicting HTF LR Down-Trend ({lr_down_count})"), (5 * mfi_up_count, mfi_up_count > 0, f"HTF MFI Up-Trend ({mfi_up_count})"), (-10 * mfi_down_count, mfi_down_count > 0, f"Conflicting MFI Down-Trend ({mfi_down_count})") ])
    else:
        factors.extend([ (10 * lr_down_count, lr_down_count > 0, f"HTF LR Down-Trend ({lr_down_count})"), (-20 * lr_up_count, lr_up_count > 0, f"Conflicting HTF LR Up-Trend ({lr_up_count})"), (5 * mfi_down_count, mfi_down_count > 0, f"HTF MFI Down-Trend ({mfi_down_count})"), (-10 * mfi_up_count, mfi_up_count > 0, f"Conflicting MFI Up-Trend ({mfi_up_count})") ])
    sma_200_1m, sma_200_15m = i.get('sma_200_1m', 0), i.get('sma_200_15m', 0)
    price_dist_from_sma_1m_pct = (current_price - sma_200_1m) / sma_200_1m * 100 if sma_200_1m else None
    price_dist_from_sma_15m_pct = (current_price - sma_200_15m) / sma_200_15m * 100 if sma_200_15m else None
    if is_long:
        if price_dist_from_sma_1m_pct and price_dist_from_sma_1m_pct < 0: factors.append((-15, True, "Price below SMA1m"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct < 0: factors.append((-15, True, "Price below SMA15m"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct > 4: factors.append((15, True, "Price above SMA15m"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct > 8: factors.append((25, True, "Price above SMA15m"))
    else:
        if price_dist_from_sma_1m_pct and price_dist_from_sma_1m_pct > 0: factors.append((-20, True, "Price above SMA1m (Risk)"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct > 0: factors.append((-20, True, "Price above SMA15m (Risk)"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct < -4: factors.append((15, True, "Price below SMA15m"))
        if price_dist_from_sma_15m_pct and price_dist_from_sma_15m_pct < -8: factors.append((25, True, "Price below SMA15m"))
    if is_long:
        if i.get('ha_3m', 'neutral') == 'green': factors.append((3, True, "HA 3m Green"))
        if i.get('ha_15m', 'neutral') == 'green': factors.append((3, True, "HA 15m Green"))
        if i.get('stoch_crossover_15m', False): factors.append((12, True, "Stoch Crossover 15m"))
        if i.get('stoch_crossover_1h', False): factors.append((12, True, "Stoch Crossover 1h"))
    else:
        if i.get('ha_3m', 'neutral') == 'red': factors.append((3, True, "HA 3m Red"))
        if i.get('ha_15m', 'neutral') == 'red': factors.append((3, True, "HA 15m Red"))
        if i.get('stoch_crossunder_15m', False): factors.append((12, True, "Stoch Crossunder 15m"))
        if i.get('stoch_crossunder_1h', False): factors.append((12, True, "Stoch Crossunder 1h"))
    for key, weight in [('0band_score', 0.2), ('0final_score_norm', 0.4), ('0prox_norm', 0.1)]:
        score = i.get(key, 0.0)
        factors.append((score * weight, True, f"{key} Modifier"))
    gain = getattr(position, 'gain', 0.0)
    if gain > 4.0: factors.append((45, True, "Position in Strong Profit > 4%"))
    elif gain > 2.0: factors.append((15, True, "Position in Profit > 2%"))
    if gain < -1.5: factors.append((-25, True, "Position in Significant Loss > -1.5%"))
    elif gain < -0.5: factors.append((-10, True, "Position in Loss > -0.5%"))
    for tf, weight in [('3m', 5), ('15m', 10), ('1h', 15)]:
        dc_high, dc_low = i.get(f'dc_high_{tf}'), i.get(f'dc_low_{tf}')
        if dc_high and dc_low and dc_low > 0:
            channel_width_pct = ((dc_high - dc_low) / dc_low) * 100
            thresholds = {'3m': (1.0, 2.5), '15m': (1.5, 3.5), '1h': (2.0, 5.0)}
            low_thresh, high_thresh = thresholds[tf]
            if channel_width_pct < low_thresh: factors.append((-weight, True, f"DC Low Volatility {tf} ({channel_width_pct:.2f}%)"))
            elif channel_width_pct > high_thresh: factors.append((weight * 0.75, True, f"DC High Volatility {tf} ({channel_width_pct:.2f}%)"))
    for points, condition, _ in factors:
        if condition: sizing_score += points
    if signal_data:
        event_type = signal_data.get('event_type', '')
        if 'winners_up' in event_type and is_long: sizing_score += 10
        elif 'losers_drop' in event_type and not is_long: sizing_score += 10
    sizing_score += 0.4 * conviction if is_long else -0.4 * conviction
    k_1h, d_1h, k_4h, d_4h = i.get('stoch_k_1h', 50), i.get('stoch_d_1h', 50), i.get('stoch_k_4h', 50), i.get('stoch_d_4h', 50)
    higher_high_1h_check = i.get('high_1h', 0) > i.get('high_1h_prev', 0) and i.get('low_1h', 0) > i.get('low_1h_prev', 0) if i.get('high_1h', 0) > 0 and i.get('high_1h_prev', 0) > 0 and i.get('low_1h', 0) > 0 and i.get('low_1h_prev', 0) > 0 else False
    lower_low_1h_check = i.get('high_1h', 0) < i.get('high_1h_prev', 0) and i.get('low_1h', 0) < i.get('low_1h_prev', 0) if i.get('high_1h', 0) > 0 and i.get('high_1h_prev', 0) > 0 and i.get('low_1h', 0) > 0 and i.get('low_1h_prev', 0) > 0 else False
    higher_high_4h_check = i.get('high_4h', 0) > i.get('high_4h_prev', 0) and i.get('low_4h', 0) > i.get('low_4h_prev', 0) if i.get('high_4h', 0) > 0 and i.get('high_4h_prev', 0) > 0 and i.get('low_4h', 0) > 0 and i.get('low_4h_prev', 0) > 0 else False
    lower_low_4h_check = i.get('high_4h', 0) < i.get('high_4h_prev', 0) and i.get('low_4h', 0) < i.get('low_4h_prev', 0) if i.get('high_4h', 0) > 0 and i.get('high_4h_prev', 0) > 0 and i.get('low_4h', 0) > 0 and i.get('low_4h_prev', 0) > 0 else False
    if is_long and (k_1h < d_1h or lower_low_1h_check): sizing_score *= 0.5
    if not is_long and (k_1h > d_1h or higher_high_1h_check): sizing_score *= 0.5
    if is_long and (k_4h < d_4h or lower_low_4h_check): sizing_score *= 0.65
    if not is_long and (k_4h > d_4h or higher_high_4h_check): sizing_score *= 0.65
    if now.weekday() >= 5 or now.hour < 14: sizing_score *= 0.5
    k_15m = i.get('stoch_k_15m', 50)
    if (is_long and k_15m > 85) or (not is_long and k_15m < 15): sizing_score *= 0.6
    clamped_score = max(-200.0, min(200.0, sizing_score))
    size_multiplier = max(0.1, min(3.0, 1.0 + (clamped_score / 250.0)))
    if config.VERBOSE2: logger.info(f"[{position_key}] SIZING: BaseQty={base_quantity:.4f}, Score={sizing_score:.1f}, Multiplier={size_multiplier:.2f}")
    final_add_qty = base_quantity * size_multiplier
    max_order_value_usd = config.MAX_ORDER_VALUE_MEN if account_key == 'men' else (config.MAX_ORDER_VALUE_FIN if account_key == 'fin' else config.MAX_ORDER_VALUE)
    if final_add_qty * current_price > max_order_value_usd:
        final_add_qty = max_order_value_usd / current_price
    if not is_long and price_dist_from_sma_1m_pct and price_dist_from_sma_1m_pct > 0.0:
        max_dangerous_position_usd = 0.5 * config.START_POSITION_SIZE
        if final_add_qty * current_price > max_dangerous_position_usd:
            final_add_qty = min(final_add_qty, max_dangerous_position_usd / current_price)
    max_pos_size_usd = get_max_position_size(symbol, account_key=account_key)
    current_notional = getattr(position, 'positionAmt', 0) * current_price
    if (current_notional + (final_add_qty * current_price)) > max_pos_size_usd:
        final_add_qty = max(0.0, (max_pos_size_usd - current_notional) / current_price)
    min_tradeable_qty = max(8 / current_price if current_price > 0 else float('inf'), trade_manager.min_qty.get(symbol, 0.0001) * 1.2) if current_price > 0 else trade_manager.min_qty.get(symbol, 0.0001) * 1.2
    if 0 < final_add_qty < min_tradeable_qty and abs(conviction) >= 55:
        final_add_qty = min_tradeable_qty
    elif final_add_qty < min_tradeable_qty:
        final_add_qty = 0.0
    try:
        market_ticker = await get_market_index_ticker()
        current_market_index = safe_fetch_float(market_ticker.get('price', 50.0), 50.0)
        cache_key = f"{account_key}:{symbol}"
        previous_market_index = _market_index_cache.get(cache_key, current_market_index)
        change_multiplier = 1.0
        level_multiplier = 1.0
        if previous_market_index and previous_market_index > 0 and abs(current_market_index - previous_market_index) > 0.1:
            market_index_change_pct = ((current_market_index - previous_market_index) / previous_market_index) * 100.0
            if is_long:
                if market_index_change_pct > 0:
                    change_multiplier = 1.0 + (market_index_change_pct / 100.0)
                else:
                    change_multiplier = 1.0 + (2.0 * market_index_change_pct / 100.0)
            else:
                if market_index_change_pct < 0:
                    change_multiplier = 1.0 + (abs(market_index_change_pct) / 100.0)
                else:
                    change_multiplier = 1.0 - (2.0 * market_index_change_pct / 100.0)
            change_multiplier = max(0.1, min(2.0, change_multiplier))
        if current_market_index > 50.0:
            bullish_strength = (current_market_index - 50.0) / 50.0
            if is_long:
                level_multiplier = 1.0 + (bullish_strength * 0.5)
            else:
                level_multiplier = 1.0 - (bullish_strength * 0.3)
        elif current_market_index < 50.0:
            bearish_strength = (50.0 - current_market_index) / 50.0
            if is_long:
                level_multiplier = 1.0 - (bearish_strength * 0.3)
            else:
                level_multiplier = 1.0 + (bearish_strength * 0.5)
        level_multiplier = max(0.5, min(1.5, level_multiplier))
        market_correction_multiplier = change_multiplier * level_multiplier
        market_correction_multiplier = max(0.1, min(2.5, market_correction_multiplier))
        final_add_qty = final_add_qty * market_correction_multiplier
        tier_mult = calculate_tier_mult(i, is_long)
        tier_min_qty = tier_mult * max(2 * config.MIN_POSITION_SIZE / current_price, trade_manager.min_qty.get(symbol, 0.0001))
        if final_add_qty < tier_min_qty and tier_mult > 0:
            logger.info(f"[{position_key}] Enforcing Tier {tier_mult} minimum: {final_add_qty:.6f} -> {tier_min_qty:.6f}")
            final_add_qty = max(final_add_qty, tier_min_qty)
        if config.VERBOSE: logger.info(f"[calculate_final_order_quantity][MARKET_INDEX_CORRECTION] {position_key}: market_index={current_market_index:.1f} prev={previous_market_index:.1f} change_mult={change_multiplier:.3f} level_mult={level_multiplier:.3f} total_mult={market_correction_multiplier:.3f} corrected_qty=${final_add_qty * current_price:.2f}")
        _market_index_cache[cache_key] = current_market_index
    except Exception as e:
        logger.debug(f"[calculate_final_order_quantity] Market index correction error: {e}")
    return max(0.0, final_add_qty)

async def _investigate_market_data_files_for_symbol(symbol: str, position_key: str, logger: logging.Logger, trade_manager=None) -> dict:
    try:
        position_key = force_usdc_if_needed(symbol.strip().upper(), getattr(trade_manager, 'available_usdc_pairs', set())) if symbol else None
        if trade_manager and hasattr(trade_manager, 'redis_manager'):
            rm = trade_manager.redis_manager
            if rm and getattr(rm, "_initialized", False):
                try:
                    raw = await rm.get(config.REDIS_KEY_MARKET_DATA, target_preference=['local', 'server'])
                    if raw:
                        data = json.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(data, dict) and position_key in data:
                            sd = data[position_key]
                            if isinstance(sd, dict):
                                mts = sd.get('timestamp')
                                if mts:
                                    for tf in ['3m', '15m', '1h', '4h', 'D']:
                                        if f'timestamp_{tf}' not in sd: sd[f'timestamp_{tf}'] = mts
                                return sd.copy()
                except Exception: pass
        import aiofiles
        search_pat = os.path.join(str(config.DATA_DIR), "market_data_*.json")
        mfs = sorted(glob.glob(search_pat), key=os.path.getmtime, reverse=True)
        mfs = [f for f in glob.glob(search_pat) if "worker" not in os.path.basename(f)]
        for mf in [f for f in mfs if "worker" not in f.name]:
            try:
                async with aiofiles.open(mf, 'r', encoding='utf-8') as f:
                    fd = json.loads(await f.read())
                    if isinstance(fd, dict) and symbol in fd:
                        sd = fd[symbol]
                        if isinstance(sd, dict):
                            fts = datetime.fromtimestamp(mf.stat().st_mtime, tz=timezone.utc).isoformat()
                            if not sd.get('timestamp'): sd['timestamp'] = fts
                            for tf in ['3m', '15m', '1h', '4h', 'D']:
                                if f'timestamp_{tf}' not in sd: sd[f'timestamp_{tf}'] = sd.get('timestamp') or fts
                            return sd.copy()
            except Exception: continue
    except Exception: pass
    return {}

async def _validate_indicator_data_freshness(i: dict, symbol: str, position_key: str, logger: logging.Logger, trade_manager=None) -> tuple[bool, str, bool]:
    if not i or not isinstance(i, dict) or not i: 
        return False, "No data", False
    hot_ts = i.get('_hot_ts')
    if hot_ts:
        try:
            latency = time.time() - float(hot_ts)
            if latency < 15.0: 
                return True, f"Hot Path Active ({latency:.2f}s)", True
        except (ValueError, TypeError):
            pass
    now = datetime.now(timezone.utc)
    mts = i.get('timestamp')
    if mts:
        for tf in ['3m', '15m', '1h', '4h', 'D']:
            if f'timestamp_{tf}' not in i: i[f'timestamp_{tf}'] = mts
    if not any(f'timestamp_{tf}' in i for tf in ['3m', '15m', '1h', '4h', 'D']):
        inv = await _investigate_market_data_files_for_symbol(symbol, position_key, logger, trade_manager)
        if inv: i.update(inv)
        else: return False, "No timestamp", False
    thresh = {'3m': 5, '15m': 20, '1h': 90, '4h': 300, 'D': 1680}
    fresh_tf = []
    for tf, t_minutes in thresh.items():
        ts_s = i.get(f'timestamp_{tf}')
        if ts_s:
            try:
                if isinstance(ts_s, (int, float)):
                    ts = datetime.fromtimestamp(ts_s, tz=timezone.utc)
                else:
                    ts = isoparse(ts_s)
                if ts.tzinfo is None: 
                    ts = ts.replace(tzinfo=timezone.utc)
                age_minutes = (now - ts).total_seconds() / 60.0
                if age_minutes <= t_minutes: 
                    fresh_tf.append(tf)
            except Exception: 
                pass
    if not fresh_tf: 
        return False, "Stale (All TFs)", False
    has_short = '3m' in fresh_tf or '15m' in fresh_tf
    return True, f"Fresh: {fresh_tf}", has_short

def _filter_position_keys(trade_manager, position_keys: list) -> list:
    """Filter position keys based on account (only process accounts this instance handles), is_symbol_allowed and LEADERBOARD_FILTER (via _check_leaderboard_allowed)."""
    filtered_keys = []
    config = getattr(trade_manager, 'config', None)
    allowed_accounts = set(getattr(config, 'ACCOUNT_KEYS', [])) if config else set()
    managed_accounts = allowed_accounts.intersection(set(trade_manager.accounts.keys()) if hasattr(trade_manager, 'accounts') else set())
    for position_key in position_keys:
        if position_key not in trade_manager.tradeable_keys:
            continue
        try:
            account_key, symbol, position_side = parse_position_key(position_key)
            if account_key not in managed_accounts:
                continue
            if not trade_manager.is_symbol_allowed(account_key, symbol, position_key):
                continue
            filtered_keys.append(position_key)
        except Exception:
            continue
    return filtered_keys
