        if abs(float(position.positionAmt)) < pos_min_qty:
            await trade_manager.cancel_empty_stop(account_key, symbol, position_key, current_price, abs(float(position.positionAmt)), require_tiny=False) # Remove stop levels for positions below minimum
        position.gain = getattr(position, 'gain', 0.0) if hasattr(position, 'gain') else 0.0
        position_prev_gain = getattr(position, 'prev_gain', 0.0) if hasattr(position, 'prev_gain') else 0.0
        position_max_quantity = 2*config.START_POSITION_SIZE/current_price
        dc_high4_3m = i.get('dc_high4_3m', 0.0); dc_low4_3m = i.get('dc_low4_3m', 0.0)
        dc_high_3m = i.get('dc_high_3m', 0.0); dc_low_3m = i.get('dc_low_3m', 0.0)
        indicator_price = safe_fetch_float(i.get('current_price', 0), current_price)
        prev_gain_valid_price_dir = False
        if position and hasattr(position, 'prev_gain_last_updated') and position.prev_gain_last_updated and position_prev_gain is not None:
            age_seconds = (now - position.prev_gain_last_updated).total_seconds()
