        if not position:
            position = trade_manager.positions_by_account.get(account_key, {}).get(position_key)
        if not position:
            position = await trade_manager._recover_position_safe(position_key, account_key, symbol, position_side)
        if not position: 
            logger.warning(f"[{position_key}] CRITICAL5: Position object vanished during processing - Aborting evaluation.")
            return f"{EvalStatus.NO_ACTION}:POSITION_LOST_RACE_CONDITION"
