        mark_price_val = safe_fetch_float(position.mark_price, 0.0)
        high_gain_min_size = safe_fetch_float(config.HIGH_GAIN_AUGMENTATION_MIN_SIZE, 200.0)
        if abs(positionAmt) * mark_price_val < 0.3 * high_gain_min_size: return
